def make_grid(side):
    g=[[4]*28 for _ in range(19)]
    for col,cells in objects.items():
        rmin=min(r for r,c in cells); rmax=max(r for r,c in cells)
        # anchor shape at row 0 or final row
        dr=0-rmin if side[col]=='U' else (18-rmax)
        for r,c in cells:
            g[r+dr][c]=col
    return g
